// friday13.cs — Friday the 13th in the proleptic Gregorian calendar
#:property PublishAot=false

// Find the earliest Friday the 13th starting from 0001-01-01
var date = new DateTime(1, 1, 13); // start checking the 13th of each month
DateTime? earliest = null;

while (date.Year == 1)
{
    if (date.DayOfWeek == DayOfWeek.Friday)
    {
        earliest = date;
        break;
    }
    date = date.AddMonths(1);
}

// If not found in year 1, search forward
if (earliest is null)
{
    date = new DateTime(2, 1, 13);
    while (true)
    {
        if (date.DayOfWeek == DayOfWeek.Friday)
        {
            earliest = date;
            break;
        }
        date = date.AddMonths(1);
    }
}

Console.WriteLine($"Earliest Friday the 13th: {earliest:yyyy-MM-dd}");
Console.WriteLine();

// Count Friday the 13ths in a full 400-year cycle (the Gregorian calendar repeats every 400 years)
int count = 0;
var start = new DateTime(1, 1, 13);
var end = new DateTime(401, 1, 1);

var current = start;
while (current < end)
{
    if (current.DayOfWeek == DayOfWeek.Friday)
        count++;
    current = current.AddMonths(1);
}

Console.WriteLine($"Friday the 13ths in a 400-year cycle: {count}");
Console.WriteLine($"Average per year: {count / 400.0:F4}");
Console.WriteLine();

// Bonus: distribution by month
var byMonth = new int[12];
current = start;
while (current < end)
{
    if (current.DayOfWeek == DayOfWeek.Friday)
        byMonth[current.Month - 1]++;
    current = current.AddMonths(1);
}

Console.WriteLine("Distribution by month:");
for (int m = 0; m < 12; m++)
    Console.WriteLine($"  {new DateTime(2000, m + 1, 1):MMMM,-10} {byMonth[m]}");

